.feather-entry-assistant nav{display:flex;gap:5px;margin:0;padding:10px 14px;background:rgba(238,234,242,.94);border-bottom:1px solid rgba(66,54,105,.14)}.feather-entry-assistant nav button{flex:1;padding:8px 12px;border:1px solid transparent;border-radius:999px;background:transparent;color:#625c72;font-weight:600}.feather-entry-assistant nav button.is-active{color:#fff;border-color:rgba(142,231,211,.24);background:linear-gradient(120deg,#62509b,#317c79);box-shadow:0 5px 14px rgba(58,49,101,.2)}
.feather-entry-workspace{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:14px;padding:14px;background-color:#eae7ed;background-image:radial-gradient(circle at 12% 16%,rgba(119,97,178,.12) 0 1px,transparent 2px),radial-gradient(circle at 82% 9%,rgba(79,156,149,.13) 0 1px,transparent 2px),linear-gradient(160deg,rgba(248,246,241,.97),rgba(232,228,239,.97));background-size:37px 37px,53px 53px,auto}.feather-entry-input,.feather-entry-output{min-width:0;padding:14px;background:rgba(255,255,255,.7);border:1px solid rgba(96,76,147,.2);box-shadow:0 8px 24px rgba(38,31,74,.06)}.feather-entry-output.has-result{border-left:3px solid #57aa9d;background:rgba(236,248,245,.72)}.feather-entry-input label{display:grid;gap:6px;color:#4b426a}.feather-entry-input input,.feather-entry-input textarea{width:100%;color:#27213f;background:rgba(255,255,255,.82);border-color:rgba(92,73,144,.3);border-radius:3px;outline:none}.feather-entry-input input:focus,.feather-entry-input textarea:focus{border-color:#6f5ca6;box-shadow:0 0 0 3px rgba(119,97,178,.12),0 0 22px rgba(142,231,211,.1)}.feather-entry-input p,.feather-entry-message{margin:8px 0;color:#777183;font-size:12px;line-height:1.6}.feather-entry-run,.feather-entry-apply{margin-top:10px;padding:9px 14px;color:#fff;border:0;border-radius:3px;background:linear-gradient(120deg,#55438d,#286b69);box-shadow:0 8px 20px rgba(57,47,103,.18)}.feather-entry-run:hover:not(:disabled),.feather-entry-apply:hover{filter:brightness(1.08)}.feather-entry-run:disabled{opacity:.45;box-shadow:none}.feather-entry-output>strong{display:block;margin-bottom:9px;color:#5d4792}.feather-entry-output ul{padding-left:18px;color:#76506f;font-size:12px}.feather-citations{margin-top:10px;font-size:12px}.feather-citations summary{color:#4d4174;cursor:pointer}.feather-citations article{margin-top:8px;padding:9px;background:rgba(255,255,255,.56);border-top:1px solid rgba(96,76,147,.16)}.feather-citations b,.feather-citations small{display:block}.feather-citations small{color:#777183}.feather-citations p{margin:4px 0;line-height:1.5}
@media(max-width:760px){.feather-entry-assistant>header{padding:13px 14px}.feather-entry-workspace{grid-template-columns:1fr}.feather-entry-assistant>header::after{display:none}}
